/// <summary>
/// Sales order load planning aid report
/// </summary>
[SRSReportParameterAttribute(classstr(METSalesOrderLoadPlanningAidContract))]
class METSalesOrderLoadPlanningAidDP extends SrsReportDataProviderPreProcessTempDB
{
    METSalesOrderLoadPlanningAidLinesTmp salesOrderLoadPlanningAidLinesTmp;
    METSalesOrderLoadPlanningAidContract        contract;

}

Method.Source:
/// <summary>
/// Invoice lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METSalesOrderLoadPlanningAidLinesTmp))]
public METSalesOrderLoadPlanningAidLinesTmp getLines()
{
    select salesOrderLoadPlanningAidLinesTmp;
    return salesOrderLoadPlanningAidLinesTmp;
}

public void processReport()
{
    contract = this.parmDataContract() as METSalesOrderLoadPlanningAidContract;

    METRoute                   routeId = contract.parmRouteID();
    SalesShippingDateConfirmed confirmedShipDateFrom = contract.parmConfirmedShipDateFrom();
    SalesShippingDateRequested confirmedShipDateTo = contract.parmConfirmedShipDateTo();
    custAccount                customerAccount = contract.parmCustAccount();
    InventLocationId           inventLocationFrom = contract.parmWareHouseId();        
    boolean                    usePrintManagement = contract.parmUsePrintManagement();

    MetReqItemTable             metReqItemTable;

    InventDim                   inventDim;
    InventDim                   inventDimReq;
    InventLocation              inventLocation;
    METInventLocation           metInventLocation;
    METIndustryKeyTable         industryKeyTable;
    SalesTable                  salesTable;
    SalesLine                   salesLine;
    ReqItemTable                reqItemTable;

    RecordInsertList            salesOrderLoadPlanningAidLineslist = new RecordInsertList(tableNum(METSalesOrderLoadPlanningAidLinesTmp), false, false, false, false, false, salesOrderLoadPlanningAidLinesTmp);
    CreatedDateTime             reportGeneratedDateTime = DateTimeUtil::getSystemDateTime();

    while select SalesId, ItemId, InventDimId, SalesUnit, SalesQty, RecId from salesLine
        join CreatedDateTime, CustAccount, InventLocationId, 
             METRoute, METSalesOrderType, SalesName, 
             ShippingDateConfirmed, METRouteStopNum, RecId 
        from salesTable
    where salesTable.SalesId == salesLine.SalesId
        && salesTable.SalesStatus == SalesStatus::Backorder
        && salesTable.DocumentStatus  != DocumentStatus::Cancelled
        && salesTable.SalesType == SalesType::Sales
        && (!routeId  || salesTable.METRoute == routeId)
        && (salesTable.ShippingDateConfirmed >=  confirmedShipDateFrom
        && salesTable.ShippingDateConfirmed <=  confirmedShipDateTo)
        && (!customerAccount || salesTable.CustAccount == customerAccount)
        && (!inventLocationFrom || salesTable.InventLocationId == inventLocationFrom)
    join inventDim
         where inventDim.inventDimId == salesLine.InventDimId
    join CovInventDimId, RecId from reqItemTable
        where reqItemTable.ItemId == salesLine.ItemId
    join OSCCode from metReqItemTable
        where metReqItemTable.RefRecId == reqItemTable.RecId
    exists join inventDimReq
        where inventDimReq.InventSiteId == inventDim.InventSiteId
        && InventDimReq.InventLocationId == inventDim.InventLocationId
        && inventDimReq.inventDimId == reqItemTable.CovInventDimId
    join Name, METWHSubEntity, RecId from inventLocation
        where inventLocation.InventLocationId == salesTable.InventLocationId
    join WHSPalletVolume from metInventLocation
            where metInventLocation.InventLocation == inventLocation.RecId
    join CompanyName from industryKeyTable
        where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity

    {
        salesOrderLoadPlanningAidLinesTmp.CompanyName = industryKeyTable.CompanyName;
        salesOrderLoadPlanningAidLinesTmp.WareHouse = inventLocation.Name;
        salesOrderLoadPlanningAidLinesTmp.ReportGeneratedDateTime = reportGeneratedDateTime;
        salesOrderLoadPlanningAidLinesTmp.Route = salesTable.METRoute;
        salesOrderLoadPlanningAidLinesTmp.ConfirmedShipDate = salesTable.ShippingDateConfirmed;
        salesOrderLoadPlanningAidLinesTmp.StopNumber = salesTable.METRouteStopNum;

        salesOrderLoadPlanningAidLinesTmp.Cases = salesLine.SalesUnit == METConstants::unitEach ? 0 : salesLine.SalesQty; 
        salesOrderLoadPlanningAidLinesTmp.Eaches = salesLine.SalesUnit == METConstants::unitEach ? salesLine.SalesQty : 0; 
        salesOrderLoadPlanningAidLinesTmp.Weight = METWHSPhysDimUOMSite::convertWeight(salesLine.ItemId, salesLine.SalesQty, salesLine.SalesUnit, inventDim);
        salesOrderLoadPlanningAidLinesTmp.Volume = METWHSPhysDimUOMSite::convertVolume(salesLine.ItemId, salesLine.SalesQty, salesLine.SalesUnit, inventDim);

        if (salesOrderLoadPlanningAidLinesTmp.Volume != 0)
        {
            salesOrderLoadPlanningAidLinesTmp.Pallets = (salesOrderLoadPlanningAidLinesTmp.Volume/metInventLocation.WHSPalletVolume);
        }
        else
        {
            salesOrderLoadPlanningAidLinesTmp.Pallets = salesOrderLoadPlanningAidLinesTmp.Volume;
        }
        salesOrderLoadPlanningAidLinesTmp.OrderCreatedDateTime = salesTable.CreatedDateTime;
        salesOrderLoadPlanningAidLinesTmp.OrderType = salesTable.METSalesOrderType;
        salesOrderLoadPlanningAidLinesTmp.OrderSplitGroup = metReqItemTable.OSCCode;
        salesOrderLoadPlanningAidLinesTmp.CustAccount = salesTable.CustAccount;
        salesOrderLoadPlanningAidLinesTmp.CustomerName = salesTable.SalesName;
        salesOrderLoadPlanningAidLineslist.add(salesOrderLoadPlanningAidLinesTmp);

    }   

    salesOrderLoadPlanningAidLineslist.insertDatabase();
}
